files.content:
.chip{
  display:inline-flex;
  align-items:center;
  gap:var(--s-1);
  position:relative;
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-weight:500;
  letter-spacing:var(--tr-snug);
  line-height:var(--lh-snug);
  white-space:nowrap;
  padding:var(--s-1) var(--s-3);
  border-radius:var(--r-full);
  border:var(--bw-1) solid var(--obsidian-700);
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  transition:border-color var(--d-quick) var(--ease-standard), color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
button.chip::before, a.chip::before{
  content:"";
  position:absolute;
  top:50%;
  left:50%;
  width:max(100%,var(--target-touch));
  height:var(--target-touch);
  transform:translate(-50%,-50%);
}
.chip .chip-dot{
  width:var(--s-1);
  height:var(--s-1);
  border-radius:var(--r-full);
  background:currentColor;
  flex:none;
}
.chip-brand, .chip-success, .chip-warn, .chip-danger, .chip-info{
  border-color:color-mix(in srgb, var(--tint-hue) calc(var(--tint-edge) * 100%), transparent);
  background:color-mix(in srgb, var(--tint-hue) calc(var(--tint-fill) * 100%), transparent);
}
.chip-brand{
  --tint-hue:var(--primary-500);
  color:var(--primary-400);
}
.chip-success{
  --tint-hue:var(--success);
  color:var(--success);
}
.chip-warn{
  --tint-hue:var(--warning);
  color:var(--warning);
}
.chip-danger{
  --tint-hue:var(--danger);
  color:var(--danger);
}
.chip-info{
  --tint-hue:var(--info);
  color:var(--info);
}
button.chip, a.chip{
  cursor:pointer;
  text-decoration:none;
}
button.chip:hover, a.chip:hover{
  border-color:var(--obsidian-600);
}
button.chip:active, a.chip:active{
  background:var(--obsidian-700);
}
button.chip[aria-pressed="true"]{
  border-color:var(--primary-500);
  color:var(--primary-400);
}
button.chip:disabled{
  opacity:var(--opacity-disabled);
  cursor:not-allowed;
}
.chip-dismiss{
  all:unset;
  cursor:pointer;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:var(--s-4);
  height:var(--s-4);
  border-radius:var(--r-full);
  color:var(--obsidian-300);
  line-height:var(--lh-tight);
  transition:color var(--d-quick) var(--ease-standard);
}
.chip-dismiss{
  position:relative;
}
.chip-dismiss::before{
  content:"";
  position:absolute;
  top:50%;
  left:50%;
  width:var(--target-touch);
  height:var(--target-touch);
  transform:translate(-50%,-50%);
}
.chip-dismiss:hover{
  color:var(--obsidian-100);
}
.chip-dismiss:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:calc(-1 * var(--s-px));
  box-shadow:var(--ring-halo);
}
@media (prefers-reduced-motion: reduce){
  .chip, .chip-dismiss{
    transition:none;
  }
}
.chip:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
